    # Objects are the non-background color components, with adjacent 5 markers
    # absorbed into the nearest colored object; pack their bounding boxes.
    h=len(grid); w=len(grid[0])
    colors=[c for row in grid for c in row if c not in (0,5)]
    seen=set(); objs=[]
    for col in dict.fromkeys(colors):
