        # include 5s adjacent (in this puzzle these are object markers)
        for r in range(h):
            for c in range(w):
                if grid[r][c]==5 and any(abs(r-a)+abs(c-b)==1 for a,b in pts): pts.add((r,c))
        if pts:
            rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
            objs.append((min(cs),col,pts))
    objs.sort()
    out=[]; x=0
    for _,col,pts in objs:
        # recolor absorbed markers and crop object
        rs=[r for r,c in pts]; cs=[c for r,c in pts]
        top,left=min(rs),min(cs); bottom,right=max(rs),max(cs)
        for r in range(len(out),max(len(out),bottom-top+1)): out.append([])
        bw=right-left+1
        for row in out: row.extend([0]*bw)
        for r,c in pts: out[r-top][x+c-left]=col
        x+=bw
    while len(out)<h: out.append([0]*x)
    return [row[:x] for row in out[:h]]"}

